import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.D0_YsCyK.js";const u=JSON.parse('{"title":"审查域 L 报告：节点管理功能深度审计","description":"","frontmatter":{},"headers":[],"relativePath":"audit/L-node-deep.md","filePath":"audit/L-node-deep.md","lastUpdated":1792448513000}'),n={name:"audit/L-node-deep.md"};function l(d,e,i,c,s,g){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="审查域-l-报告-节点管理功能深度审计" tabindex="-1">审查域 L 报告：节点管理功能深度审计 <a class="header-anchor" href="#审查域-l-报告-节点管理功能深度审计" aria-label="Permalink to &quot;审查域 L 报告：节点管理功能深度审计&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：节点 CRUD 级联、延迟探测、调优、路由追踪、节点升级、导入解析</li><li>发现问题数：P0 0 个 / P1 1 个 / P2 5 个 / P3 4 个</li><li>实际执行的测试：<code>go test ./internal/kernel/ -run TestParse|TestImport</code> 通过；<code>go build ./...</code> 通过</li></ul><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><h3 id="l-001-nodebatchupgrade-的-goroutine-泄漏风险" tabindex="-1">L-001：<code>nodeBatchUpgrade</code> 的 goroutine 泄漏风险 <a class="header-anchor" href="#l-001-nodebatchupgrade-的-goroutine-泄漏风险" aria-label="Permalink to &quot;L-001：`nodeBatchUpgrade` 的 goroutine 泄漏风险&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/upgrade.go:285-300</code></li><li><strong>现象</strong>：<code>for i, id := range req.IDs</code> 循环中先 <code>wg.Add(1)</code> 再 <code>go func()</code>，goroutine 内部 <code>sem &lt;- struct{}{}</code> 阻塞等待信号量。如果 <code>req.IDs</code> 很大（如 1000 个节点），会瞬间启动 1000 个 goroutine，大部分阻塞在 sem 等待，浪费内存。</li><li><strong>复现</strong>：POST <code>/api/v1/node/upgrade/batch</code> with <code>{&quot;ids&quot;: [1,2,...,1000]}</code>。</li><li><strong>期望</strong>：使用 worker pool 模式，限制 goroutine 总数。</li><li><strong>实际</strong>：goroutine 数 = IDs 数，无上限。</li><li><strong>影响范围</strong>：批量升级大量节点时内存 spike。</li><li><strong>修复方向</strong>：将 <code>sem &lt;- struct{}{}</code> 移到 <code>go func()</code> 之前（主循环中限流），或改用固定 worker 池。</li></ul><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="l-002-probenodelatency-tracenoderoutes-的-ctx-取消后仍等待" tabindex="-1">L-002：<code>probeNodeLatency</code> / <code>traceNodeRoutes</code> 的 ctx 取消后仍等待 <a class="header-anchor" href="#l-002-probenodelatency-tracenoderoutes-的-ctx-取消后仍等待" aria-label="Permalink to &quot;L-002：`probeNodeLatency` / `traceNodeRoutes` 的 ctx 取消后仍等待&quot;">​</a></h3><ul><li><strong>文件</strong>： <ul><li><code>go-backend/internal/http/handler/node_latency.go:274-290</code></li><li><code>go-backend/internal/http/handler/node_route.go:243-265</code></li></ul></li><li><strong>现象</strong>：<code>if ctx.Err() != nil { break }</code> 只跳出任务分发循环，但 <code>wg.Wait()</code> 会等待已启动的 goroutine 全部完成。每个 ping 最长约 14 秒（4 次 × 2.2 秒 + 5 秒），ctx 取消后请求仍可能 hang 住。</li><li><strong>期望</strong>：ctx 取消后快速返回。</li><li><strong>实际</strong>：等待所有已启动探测完成。</li><li><strong>修复方向</strong>：<code>nodeLatencyPing</code> / <code>nodeTraceroute</code> 内部检查 ctx，或使用 <code>errgroup.WithContext</code>。</li></ul><h3 id="l-003-hopasncache-无上限-内存泄漏风险" tabindex="-1">L-003：<code>hopASNCache</code> 无上限，内存泄漏风险 <a class="header-anchor" href="#l-003-hopasncache-无上限-内存泄漏风险" aria-label="Permalink to &quot;L-003：`hopASNCache` 无上限，内存泄漏风险&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_route.go:52-53</code></li><li><strong>现象</strong>：<code>hopASNCache = make(map[string]string)</code> 是全局 map，只增不减。每次路由追踪遇到新的 CMI IP 都会缓存。长期运行的面板会无限增长。</li><li><strong>期望</strong>：LRU 上限或定期清理。</li><li><strong>实际</strong>：无上限。</li><li><strong>修复方向</strong>：加 <code>maxHopASNCacheSize</code>（如 10000），超限时清空或 LRU 淘汰。</li></ul><h3 id="l-004-cmi-hop-的-dns-查询串行执行" tabindex="-1">L-004：CMI hop 的 DNS 查询串行执行 <a class="header-anchor" href="#l-004-cmi-hop-的-dns-查询串行执行" aria-label="Permalink to &quot;L-004：CMI hop 的 DNS 查询串行执行&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_route.go:175-186</code>（<code>routePointFrom</code> 调用 <code>refineHopNet</code>）</li><li><strong>现象</strong>：<code>routePointFrom</code> 为每个 hop 调用 <code>refineHopNet(ip, ...)</code>，CMI 的 hop 会触发 <code>hopOriginASN</code> 的 DNS 查询（2 秒超时）。10 个 CMI hop 串行 = 最长 20 秒，拖慢整个追踪响应。</li><li><strong>期望</strong>：并发查询或批量查询。</li><li><strong>实际</strong>：串行。</li><li><strong>修复方向</strong>：在 <code>traceNodeRoutes</code> 的 goroutine 内对 hops 并发做 ASN 查询。</li></ul><h3 id="l-005-nodeupgrade-允许降级到旧版本" tabindex="-1">L-005：<code>nodeUpgrade</code> 允许降级到旧版本 <a class="header-anchor" href="#l-005-nodeupgrade-允许降级到旧版本" aria-label="Permalink to &quot;L-005：`nodeUpgrade` 允许降级到旧版本&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/upgrade.go:177-230</code></li><li><strong>现象</strong>：只校验版本号格式（<code>isValidAgentVersion</code>），不比较目标版本与当前版本。用户可误操作将节点从 1.0.5 降级到 1.0.0。</li><li><strong>期望</strong>：目标版本 &lt; 当前版本时警告或拒绝。</li><li><strong>实际</strong>：无检查。</li><li><strong>修复方向</strong>：查询节点当前版本，与目标版本做语义比较，降级时要求二次确认。</li></ul><h3 id="l-006-调优写入失败时删除历史备份-引用-c-报告" tabindex="-1">L-006：调优写入失败时删除历史备份（引用 C 报告） <a class="header-anchor" href="#l-006-调优写入失败时删除历史备份-引用-c-报告" aria-label="Permalink to &quot;L-006：调优写入失败时删除历史备份（引用 C 报告）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-gost/x/socket/tuning.go:276-281</code></li><li><strong>现象</strong>：二次调优时若内核拒绝写入（EINVAL），<code>delete(backup, k)</code> 会删除第一次调优时保存的原始值备份，导致以后无法恢复到真正的原始值。</li><li><strong>报告</strong>：C-node.md 已详细记录，此处引用。</li></ul><h2 id="p3-体验-建议" tabindex="-1">P3 体验/建议 <a class="header-anchor" href="#p3-体验-建议" aria-label="Permalink to &quot;P3 体验/建议&quot;">​</a></h2><h3 id="l-007-latencyprobe-取最大延迟而非平均值" tabindex="-1">L-007：<code>latencyProbe</code> 取最大延迟而非平均值 <a class="header-anchor" href="#l-007-latencyprobe-取最大延迟而非平均值" aria-label="Permalink to &quot;L-007：`latencyProbe` 取最大延迟而非平均值&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_latency.go:306-312</code></li><li><strong>现象</strong>：<code>if pt.LatencyMs &gt; p.LatencyMs { p.LatencyMs = pt.LatencyMs }</code> 取所有测试点中的最大值作为节点延迟。语义上通常应显示平均值或最小值，最大值会让节点看起来比实际慢。</li><li><strong>备注</strong>：可能是有意为之（保守估计），如为有意请在注释中说明。</li></ul><h3 id="l-008-nodetune-的-groups-参数无白名单校验" tabindex="-1">L-008：<code>nodeTune</code> 的 Groups 参数无白名单校验 <a class="header-anchor" href="#l-008-nodetune-的-groups-参数无白名单校验" aria-label="Permalink to &quot;L-008：`nodeTune` 的 Groups 参数无白名单校验&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_tune.go:33-37</code></li><li><strong>现象</strong>：<code>req.Groups</code> 直接透传给 agent（<code>map[string]interface{}{&quot;groups&quot;: req.Groups}</code>），无白名单校验。非法组名依赖 agent 侧处理。</li><li><strong>修复方向</strong>：在 handler 层加白名单（bbr/buffer/tcp/backlog/forward/files）。</li></ul><h3 id="l-009-nodelatencytargetsset-未验证节点-id-存在性" tabindex="-1">L-009：<code>nodeLatencyTargetsSet</code> 未验证节点 ID 存在性 <a class="header-anchor" href="#l-009-nodelatencytargetsset-未验证节点-id-存在性" aria-label="Permalink to &quot;L-009：`nodeLatencyTargetsSet` 未验证节点 ID 存在性&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_latency.go:476</code></li><li><strong>现象</strong>：直接调用 <code>SetNodesLatencyTargets(req.IDs, value)</code>，IDs 包含不存在的节点时静默成功。</li><li><strong>修复方向</strong>：校验 IDs 对应的节点存在，或返回实际更新的数量。</li></ul><h3 id="l-010-classifyroute-多骨干网优先级" tabindex="-1">L-010：<code>classifyRoute</code> 多骨干网优先级 <a class="header-anchor" href="#l-010-classifyroute-多骨干网优先级" aria-label="Permalink to &quot;L-010：`classifyRoute` 多骨干网优先级&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/node_route.go:106-123</code></li><li><strong>现象</strong>：同时检测到 9929 和 4837 时只返回&quot;联通 9929&quot;。实际中几乎不会同时出现，低优先级。</li></ul><h2 id="已验证通过" tabindex="-1">已验证通过 <a class="header-anchor" href="#已验证通过" aria-label="Permalink to &quot;已验证通过&quot;">​</a></h2><ol><li><strong>节点级联删除完整</strong>：<code>DeleteNodeCascade</code>（<code>repository_mutations.go:392</code>）经 <code>deleteNodeKernelsTx</code>（<code>repository_kernel.go:112</code>）覆盖 NodeInbound/NodeInboundRelay/NodeInboundCounter，无孤儿数据。</li><li><strong>导入解析健壮</strong>：<code>finishProxy</code>（<code>proxy_parse.go:89</code>）有端口范围（1-65535）、主机、凭据三重校验；<code>parseVMessURI</code> 的 JSON 解析失败有明确错误。</li><li><strong>升级 S-02 防护到位</strong>：版本号正则 <code>^v?[0-9]+\\.[0-9]+\\.[0-9]+$</code> 防路径穿越；面板不再发送 downloadUrl，由 agent 本地拼接。</li><li><strong>延迟配置校验完整</strong>：<code>parseLatencyTargets</code> 有数量（10）、名称（20字）、重名、地址有效性、pinned 上限（3）五重校验。</li><li><strong>路由线路识别</strong>：9 个骨干网前缀 + CMI 的 ASN 二次细分（58807→CMIN2），逻辑正确。</li></ol><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li>真实节点延迟探测的耗时和准确性（需真实节点）</li><li>真实路由追踪的线路识别准确率（需真实线路）</li><li>节点升级的端到端流程（需真实节点 agent）</li><li>大批量（100+）节点并发探测时的面板负载</li></ul>',30)])])}const p=o(n,[["render",l]]);export{u as __pageData,p as default};
